def rotate_right(xs, n):
    """Returns xs rotated right by n positions."""
    if not isinstance(xs, list):
        raise TypeError("xs must be a list")
    if not xs:
        return []
    m = len(xs)
    return [xs[(i - n) % m] for i in range(m)]
```

