def rle(s):
    """Returns the run-length encoding of s as a list of [char, count] pairs."""
    if not isinstance(s, str):
        raise TypeError("s must be a string")
    out = []
    for ch in s:
        if out and out[-1][0] == ch:
            out[-1][1] += 1
        else:
            out.append([ch, 1])
    return out
```

